templates.prisma:
datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

generator client {
  provider = "prisma-client-js"
}

model Users {
  id String @id @default(uuid()) // Primary key for the user.
  email String @unique // User's email address, used for login.
  password_hash String // Hashed password for secure authentication.
  username String @unique // Unique username for display.
  profile_picture_url String? // URL to the user's profile picture.
  github_id String? @unique // GitHub ID for OAuth integration.
  learning_level String @default("'junior'") // User's self-declared learning level (junior, mid, senior).
  interests Json? // Array of user's programming interests/topics.
  created_at DateTime // Timestamp of user creation.
  updated_at DateTime // Timestamp of last profile update.
}

model Topics {
  id String @id @default(uuid()) // Primary key for the topic.
  name String @unique // Name of the topic (e.g., 'React Hooks').
  slug String @unique // URL-friendly identifier for the topic.
  description String? // Brief description of the topic.
  parent_topic_id String? // Self-referencing foreign key for hierarchical topics.
  created_at DateTime // Timestamp of topic creation.
  updated_at DateTime // Timestamp of last topic update.

  // Relations:
  // [one-to-many] -> Topics (via parent_topic_id) [references]
}

model Lessons {
  id String @id @default(uuid()) // Primary key for the lesson.
  title String // Title of the micro-lesson.
  slug String @unique // URL-friendly identifier for the lesson.
  description String // Short summary of the lesson content.
  content_html String // Full HTML content of the lesson, including code snippets and diagrams.
  ai_prompt String? // The original prompt used for AI generation.
  generated_by_user_id String? // ID of the user who initiated the AI generation (if any).
  topic_id String // Foreign key to the primary topic this lesson belongs to.
  difficulty_level String @default("'beginner'") // Difficulty level of the lesson.
  programming_languages Json? // Array of programming languages covered in the lesson.
  status String @default("'pending_review'") // Current status of the lesson (draft, pending_review, published, rejected).
  review_notes String? // Notes from content moderation.
  created_at DateTime // Timestamp of lesson creation.
  updated_at DateTime // Timestamp of last lesson update.
  published_at DateTime? // Timestamp when the lesson was published.

  // Relations:
  // [many-to-one] -> Users (via generated_by_user_id) [references]
  // [many-to-one] -> Topics (via topic_id) [references]
}

model UserLessons {
  id String @id @default(uuid()) // Primary key for user-lesson progress.
  user_id String // Foreign key to the user.
  lesson_id String // Foreign key to the lesson.
  status String @default("'started'") // Current status of user's engagement with the lesson.
  progress_percentage Int @default(0) // Percentage of the lesson completed (0-100).
  last_viewed_at DateTime // Timestamp of the last time the user viewed this lesson.
  completed_at DateTime? // Timestamp when the user completed the lesson.
  score Float? // Aggregate score from quizzes/challenges within the lesson.
  xp_earned Int? // Experience points gained from completing the lesson.
  created_at DateTime // Timestamp of initial lesson interaction.
  updated_at DateTime // Timestamp of last progress update.

  // Relations:
  // [many-to-one] -> Users (via user_id) [references]
  // [many-to-one] -> Lessons (via lesson_id) [references]
}

model Quizzes {
  id String @id @default(uuid()) // Primary key for the quiz.
  lesson_id String // Foreign key to the associated lesson.
  title String // Title of the quiz.
  questions Json // Array of question objects (type, text, options, correct_answer, code_snippet, expected_output).
  ai_generated Boolean @default(TRUE) // Indicates if the quiz was AI-generated.
  created_at DateTime // Timestamp of quiz creation.
  updated_at DateTime // Timestamp of last quiz update.

  // Relations:
  // [one-to-one] -> Lessons (via lesson_id) [references]
}

model UserQuizAttempts {
  id String @id @default(uuid()) // Primary key for the quiz attempt.
  user_id String // Foreign key to the user.
  quiz_id String // Foreign key to the quiz.
  answers Json // JSON object storing user's answers to the quiz questions.
  score Float? // Percentage score achieved in the quiz attempt.
  passed Boolean? // Indicates if the user passed the quiz based on a threshold.
  attempt_number Int @default(1) // The sequential number of this attempt for the given user and quiz.
  submitted_at DateTime // Timestamp when the quiz was submitted.
  created_at DateTime // Timestamp of creation.
  updated_at DateTime // Timestamp of last update.

  // Relations:
  // [many-to-one] -> Users (via user_id) [references]
  // [many-to-one] -> Quizzes (via quiz_id) [references]
}

model Discussions {
  id String @id @default(uuid()) // Primary key for the discussion comment.
  lesson_id String // Foreign key to the lesson the comment is about.
  user_id String // Foreign key to the user who posted the comment.
  parent_comment_id String? // Self-referencing foreign key for threaded replies.
  content String // The content of the discussion comment.
  is_ai_response Boolean @default(FALSE) // Indicates if the comment was generated by an AI tutor.
  created_at DateTime // Timestamp of comment creation.
  updated_at DateTime // Timestamp of last comment update.

  // Relations:
  // [many-to-one] -> Lessons (via lesson_id) [references]
  // [many-to-one] -> Users (via user_id) [references]
  // [one-to-many] -> Discussions (via parent_comment_id) [references]
}

model Subscriptions {
  id String @id @default(uuid()) // Primary key for the subscription.
  user_id String // Foreign key to the subscribing user.
  plan_id String // Identifier for the subscription plan (e.g., 'pro-monthly').
  stripe_customer_id String @unique // Stripe Customer ID for payment processing.
  stripe_subscription_id String @unique // Stripe Subscription ID for managing the subscription.
  status String @default("'active'") // Current status of the subscription.
  start_date DateTime // Date when the subscription started.
  end_date DateTime? // Date when the subscription is scheduled to end.
  auto_renew Boolean @default(TRUE) // Indicates if the subscription automatically renews.
  created_at DateTime // Timestamp of subscription creation.
  updated_at DateTime // Timestamp of last subscription update.

  // Relations:
  // [one-to-one] -> Users (via user_id) [references]
}

