const SubscriptionsSchema = new mongoose.Schema({
  user_id: {
    type: String,
    required: true,
    description: "Foreign key to the subscribing user."
  },
  plan_id: {
    type: String,
    required: true,
    description: "Identifier for the subscription plan (e.g., 'pro-monthly')."
  },
  stripe_customer_id: {
    type: String,
    required: true,
    unique: true,
    description: "Stripe Customer ID for payment processing."
  },
  stripe_subscription_id: {
    type: String,
    required: true,
    unique: true,
    description: "Stripe Subscription ID for managing the subscription."
  },
  status: {
    type: String,
    required: true,
    default: "'active'",
    description: "Current status of the subscription."
  },
  start_date: {
    type: Date,
    required: true,
